function decision = resolveSRSPUSCHCollision(cfg, grant, absoluteSlotOneBased)
%RESOLVESRSPUSCHCOLLISION Exact same-UE SRS/PUSCH RE collision decision.
%
% The decision is independent of the duplex scheme.  FDD/TDD authority
% determines whether an UL occasion exists; once it does, the actual
% carrier, SRS and scheduled PUSCH objects determine resource ownership.
% Coordinates are generated by 5G Toolbox and compared after removing the
% antenna-port dimension because one UE cannot claim the same time/frequency
% RE for SRS and PUSCH merely by assigning different logical ports.

arguments
    cfg (1,1) struct
    grant (1,1) struct
    absoluteSlotOneBased (1,1) double {mustBeFinite,mustBeInteger,mustBePositive}
end

duplexMode = sixgr.phy.frame.resolveDuplexMode(cfg);
slot0 = double(absoluteSlotOneBased) - 1;
[carrierProbe, ~] = sixgr.phy.grid.makeCarrier(cfg);
slotsPerFrame = localSlotsPerFrame(carrierProbe);
slotWithinFrame0 = mod(slot0, slotsPerFrame);
frame0 = floor(slot0 / slotsPerFrame);
[carrier, ~] = sixgr.phy.grid.makeCarrier(cfg, ...
    "Slot", slotWithinFrame0, "Frame", frame0);

strictSRS = sixgr.phy.srs.buildSRSConfigFromScenario(cfg);
srs = strictSRS.ToolboxSRS;
srsAllocation = sixgr.phy.frame.ChannelAllocationMaterializer. ...
    materializeReferenceSignal(carrier, "SRS", srs, ...
    "AbsoluteSlot", slot0);

pusch = localResolvePUSCH(carrier, cfg, grant);
puschAllocation = sixgr.phy.frame.ChannelAllocationMaterializer. ...
    materializePUSCH(carrier, pusch, "AbsoluteSlot", slot0);

srsCoordinates = localTimeFrequencyCoordinates( ...
    srsAllocation.ActualCoordinates0Based);
puschCoordinates = localTimeFrequencyCoordinates( ...
    puschAllocation.ActualCoordinates0Based);
overlapCoordinates = intersect(srsCoordinates, puschCoordinates, ...
    "rows", "stable");
collision = ~isempty(overlapCoordinates);

if collision
    action = "defer_srs_preserve_scheduled_pusch";
    status = "COLLISION_RESOLVED";
else
    action = "execute_srs";
    status = "NO_COLLISION";
end

decision = struct( ...
    "ContractVersion", "sixgr_srs_pusch_exact_re_collision/v1", ...
    "DuplexMode", string(duplexMode), ...
    "AbsoluteSlotOneBased", double(absoluteSlotOneBased), ...
    "AbsoluteSlotZeroBased", slot0, ...
    "SlotWithinFrameZeroBased", slotWithinFrame0, ...
    "FrameZeroBased", frame0, ...
    "UEIndex", double(sixgr.util.structGet(grant, "UEIndex", NaN)), ...
    "SRSRECount", double(size(srsCoordinates, 1)), ...
    "PUSCHRECount", double(size(puschCoordinates, 1)), ...
    "OverlapRECount", double(size(overlapCoordinates, 1)), ...
    "Collision", logical(collision), ...
    "Action", string(action), ...
    "Status", string(status), ...
    "SRSAllocationSource", string(srsAllocation.ToolboxSource), ...
    "PUSCHAllocationSource", string(puschAllocation.ToolboxSource), ...
    "ResourceComparisonDomain", "subcarrier_symbol_same_ue", ...
    "Exact", true, ...
    "ApproximationUsed", false, ...
    "OverlapCoordinates0Based", overlapCoordinates);
end

function pusch = localResolvePUSCH(carrier, cfg, grant)
configured = sixgr.util.structGet(grant, "PUSCHConfig", []);
if isa(configured, "nrPUSCHConfig")
    pusch = configured;
    return;
end

prbSet = localRequiredNumericVector(grant, "PRBSet");
symbolAllocation = localRequiredNumericVector(grant, "SymbolAllocation");
if numel(symbolAllocation) ~= 2
    error("sixgr:phy:frame:InvalidScheduledPUSCHSymbolAllocation", ...
        "Scheduled PUSCH SymbolAllocation must contain [start length].");
end
modulation = strtrim(string(sixgr.util.structGet(grant, "Modulation", "")));
if strlength(modulation) == 0
    error("sixgr:phy:frame:MissingScheduledPUSCHModulation", ...
        "Exact SRS/PUSCH collision resolution requires grant.Modulation.");
end
numLayers = double(sixgr.util.structGet(grant, "NumLayers", ...
    sixgr.util.structGet(grant, "Layers", NaN)));
if ~(isscalar(numLayers) && isfinite(numLayers) && numLayers >= 1)
    error("sixgr:phy:frame:MissingScheduledPUSCHLayers", ...
        "Exact SRS/PUSCH collision resolution requires grant.NumLayers.");
end
rnti = double(sixgr.util.structGet(grant, "RNTI", ...
    sixgr.util.structGet(cfg, "phy.pusch.RNTI", ...
    sixgr.util.structGet(cfg, "phy.rnti", NaN))));

args = {"PRBSet", prbSet, ...
    "SymbolAllocation", symbolAllocation, ...
    "Modulation", char(modulation), ...
    "NumLayers", numLayers, ...
    "RNTI", rnti};
optional = { ...
    "TransformPrecoding", "TransformPrecoding"; ...
    "TransmissionScheme", "TransmissionScheme"; ...
    "NumAntennaPorts", "NumAntennaPorts"; ...
    "TPMI", "TPMI"; ...
    "NID", "NID"; ...
    "MappingType", "MappingType"};
for index = 1:size(optional, 1)
    value = sixgr.util.structGet(grant, optional{index, 2}, []);
    if ~isempty(value)
        args = [args, optional(index, 1), {value}]; %#ok<AGROW>
    end
end
[~, ~, pusch] = sixgr.phy.grid.allocREsPUSCH(carrier, cfg, args{:});
end

function value = localRequiredNumericVector(s, fieldName)
value = sixgr.util.structGet(s, fieldName, []);
if ~(isnumeric(value) && isreal(value) && ~isempty(value) && ...
        all(isfinite(double(value(:)))))
    error("sixgr:phy:frame:MissingScheduledPUSCHAllocation", ...
        "Exact SRS/PUSCH collision resolution requires grant.%s.", ...
        char(fieldName));
end
value = double(value(:).');
end

function coordinates = localTimeFrequencyCoordinates(raw)
raw = double(raw);
if isempty(raw)
    coordinates = zeros(0, 2);
    return;
end
if size(raw, 2) < 2 || any(~isfinite(raw(:, 1:2)), "all")
    error("sixgr:phy:frame:InvalidExactRECoordinates", ...
        "Exact RE coordinates must contain finite subcarrier and symbol columns.");
end
coordinates = unique(raw(:, 1:2), "rows", "stable");
end

function value = localSlotsPerFrame(carrier)
scs = double(carrier.SubcarrierSpacing);
mu = log2(scs / 15);
if ~(isfinite(mu) && abs(mu - round(mu)) < 1e-9 && mu >= 0)
    error("sixgr:phy:frame:InvalidCarrierNumerology", ...
        "Carrier subcarrier spacing %g kHz does not resolve an NR numerology.", scs);
end
value = 10 * 2^round(mu);
end
